const q=(s,c=document)=>c.querySelector(s),qa=(s,c=document)=>[...c.querySelectorAll(s)];
const all=(window.CHASER_VEHICLES||[]).filter(v=>['published','sold'].includes(v.publicationStatus));
const slug=location.pathname.startsWith('/cars/')?location.pathname.split('/').filter(Boolean).pop():(new URLSearchParams(location.search).get('slug')||new URLSearchParams(location.search).get('id'));
const vehicle=all.find(v=>v.slug===slug||v.id===slug)||all[0];
const money=n=>n==null?'Enquire':`US$${Number(n).toLocaleString('en-US')}`,number=n=>Number(n).toLocaleString('en-US');
const name=v=>`${v.listingYear||v.year||''} ${v.make} ${v.model}${v.trim?` ${v.trim}`:''}`.trim(),asset=p=>p.startsWith('/')?p:`/${p}`;
const waText=v=>`Hello Chaser Motors, I'm interested in the ${name(v)} listed at ${money(v.price)}. Please send me more information.`,wa=v=>`https://wa.me/263788265454?text=${encodeURIComponent(waText(v))}`;
const specs=v=>[["Year / registration",v.month?`${v.year}/${v.month}`:v.year],["Mileage",v.mileageKm?`${number(v.mileageKm)} km`:null],["Engine",v.engineCc?`${number(v.engineCc)}cc`:null],["Transmission",v.transmission],["Fuel",v.fuel],["Body class",v.bodyClass],["Colour",v.exteriorColour]].filter(x=>x[1]);
function price(v){if(v.inspectionPrice&&v.noInspectionPrice)return `<div class="detail-price dual"><div><span>${v.make==='Honda'?'CIF · ':''}WITH INSPECTION</span><strong>${money(v.inspectionPrice)}</strong><small>${v.destinationPort}</small></div><div><span>${v.make==='Honda'?'C&F · ':''}WITHOUT INSPECTION</span><strong>${money(v.noInspectionPrice)}</strong><small>${v.destinationPort}</small></div></div>`;return `<div class="detail-price"><span>${v.pricingType||'Vehicle price'}</span><strong>${money(v.price)}</strong><small>${v.pricingNote||''}</small></div>`}
const related=all.filter(v=>v.id!==vehicle.id).sort((a,b)=>{const score=x=>(x.bodyClass===vehicle.bodyClass?4:0)+(x.make===vehicle.make?2:0)+(x.fuel===vehicle.fuel?1:0);return score(b)-score(a)}).slice(0,3);
document.title=`${name(vehicle)} | Chaser Motors`;q('meta[name="description"]').content=`View ${name(vehicle)} specifications, pricing and enquiry options from Chaser Motors.`;
q('#main').innerHTML=`<section class="detail-hero"><div class="container"><a class="detail-back" href="/#cars">← Back to inventory</a><div class="detail-layout"><div class="media-gallery"><button class="media-main" aria-label="Open image gallery"><img src="${asset(vehicle.featuredImage)}" alt="${name(vehicle)}"><span class="media-count">01 / ${String(vehicle.images.length).padStart(2,'0')}</span></button><div class="media-strip">${vehicle.images.map((im,i)=>`<button data-media="${i}" class="${i===0?'active':''}"><img src="${asset(im)}" alt="${name(vehicle)} angle ${i+1}"></button>`).join('')}${vehicle.videos.map((vid,i)=>`<button class="video-thumb" data-video="${i}">▶<span>${vid.type}</span></button>`).join('')}</div></div><aside class="vehicle-summary"><div class="detail-labels"><span>${vehicle.offerLabel||vehicle.status}</span><span>${vehicle.status}</span></div><p class="eyebrow">${vehicle.make} · ${vehicle.bodyClass}</p><h1>${name(vehicle)}</h1>${price(vehicle)}<div class="summary-specs">${specs(vehicle).slice(0,5).map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><div class="detail-ctas"><button class="split-action enquire"><span>ASK ABOUT THIS CAR</span><i>↗</i></button><a class="secondary-action" href="${wa(vehicle)}"><span>＋</span> WHATSAPP</a></div></aside></div></div></section><section class="detail-content"><div class="container detail-content-grid"><div><p class="eyebrow">Vehicle details</p><h2>Confirmed specifications</h2><div class="spec-table">${specs(vehicle).map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div></div><div><p class="eyebrow">Features</p><h2>Included equipment</h2>${vehicle.features.length?`<div class="feature-list">${vehicle.features.map(f=>`<span>✓ ${f}</span>`).join('')}</div>`:'<p class="muted">Additional features have not been supplied. Ask Chaser Motors for confirmed details.</p>'}<div class="import-note"><strong>Import information</strong><p>${vehicle.fullDescription}</p><p>${vehicle.destinationPort?`Destination: ${vehicle.destinationPort}.`:''} Confirm final charges and availability directly with Chaser Motors.</p></div></div></div></section><section class="similar-section"><div class="container"><p class="eyebrow">You may also like</p><h2>Similar vehicles</h2><div class="similar-grid">${related.map(v=>`<a href="/cars/${v.slug}" class="similar-card"><img src="${asset(v.thumbnail)}" alt="${name(v)}" loading="lazy"><span>${v.bodyClass}</span><strong>${name(v)}</strong><b>${money(v.price)}</b></a>`).join('')}</div></div></section>`;
let index=0;const mainImg=q('.media-main img');function showImage(i){index=(i+vehicle.images.length)%vehicle.images.length;mainImg.src=asset(vehicle.images[index]);q('.media-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(vehicle.images.length).padStart(2,'0')}`;qa('[data-media]').forEach((b,n)=>b.classList.toggle('active',n===index))}qa('[data-media]').forEach(b=>b.onclick=()=>showImage(Number(b.dataset.media)));
const viewer=q('.gallery-viewer');function openViewer(){q('img',viewer).src=asset(vehicle.images[index]);q('.viewer-count').textContent=`${String(index+1).padStart(2,'0')} / ${String(vehicle.images.length).padStart(2,'0')}`;viewer.classList.add('open');viewer.setAttribute('aria-hidden','false');document.body.classList.add('locked')}function closeViewer(){viewer.classList.remove('open');viewer.setAttribute('aria-hidden','true');document.body.classList.remove('locked')}q('.media-main').onclick=openViewer;q('.viewer-close').onclick=closeViewer;q('.viewer-prev').onclick=()=>{showImage(index-1);openViewer()};q('.viewer-next').onclick=()=>{showImage(index+1);openViewer()};
let touchX=0;q('.media-main').addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});q('.media-main').addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchX;if(Math.abs(delta)>45)showImage(index+(delta<0?1:-1))},{passive:true});
const modal=q('.modal-layer');function openVideo(i){const media=vehicle.videos[i];if(!media)return;const embed=/youtube\.com|youtu\.be|vimeo\.com/.test(media.url);q('.modal-content').innerHTML=`<div class="video-modal"><div class="video-frame">${embed?`<iframe src="${media.url}" title="${media.type||'Vehicle video'}" allow="fullscreen" loading="lazy"></iframe>`:`<video controls preload="metadata" poster="${asset(media.poster||vehicle.featuredImage)}"><source src="${media.url}"></video>`}</div><p class="eyebrow">${media.type||'Vehicle video'}</p><h2>${name(vehicle)}</h2><button class="secondary-action video-enquire"><span>＋</span> ASK ABOUT THIS VEHICLE</button></div>`;modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('locked');q('.video-enquire').onclick=enquiry}qa('[data-video]').forEach(b=>b.onclick=()=>openVideo(Number(b.dataset.video)));function enquiry(){q('.modal-content').innerHTML=`<div class="enquiry-panel"><p class="eyebrow">Vehicle enquiry</p><h2>Ask about this car</h2><p>${name(vehicle)}</p><form id="enquiry-form"><label>Name<input name="name" required autocomplete="name"></label><label>WhatsApp number<input name="phone" type="tel" required autocomplete="tel"></label><label>Message<textarea name="message">${waText(vehicle)}</textarea></label><button class="split-action" type="submit"><span>SEND ON WHATSAPP</span><i>↗</i></button><a class="secondary-action" href="tel:+263788265454"><span>＋</span> CALL CHASER</a></form></div>`;modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('locked');q('#enquiry-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);location.href=`https://wa.me/263788265454?text=${encodeURIComponent(`${d.get('message')}\n\nName: ${d.get('name')}\nWhatsApp: ${d.get('phone')}`)}`}}function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('locked')}q('.enquire').onclick=enquiry;q('#mobile-enquire').onclick=enquiry;q('.modal-close').onclick=closeModal;q('.modal-scrim').onclick=closeModal;q('#mobile-wa').href=wa(vehicle);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeViewer();closeModal()}});
